INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'boundary', 'n.', '/ˈbaʊnd(ə)ri/', '分界线;边界;界限', 'True friendship knows no boundary between people of different cultures.', '真正的友谊不分文化、没有界限。', 'Breaking Boundaries', 1, 0, 'senior', 'wordlist', 'elective2', 'U4', 'break boundaries', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'statistic', 'n.', '/stəˈtɪstɪk/', '(一项)统计数据', 'Every statistic in the report points to a rising number of volunteers.', '报告中的每一项统计数据都显示志愿者人数在上升。', 'Breaking Boundaries', 2, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a worrying statistic', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'assist', 'v.', '/əˈsɪst/', '协助,帮助', 'Local volunteers assist the doctors in the busy clinic every day.', '当地志愿者每天在繁忙的诊所协助医生。', 'Breaking Boundaries', 3, 0, 'senior', 'wordlist', 'elective2', 'U4', 'assist the doctors', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'tackle', 'v.', '/ˈtæk(ə)l/', '处理,对付(难题)', 'Doctors from many countries came together to tackle the disease.', '来自许多国家的医生齐心协力对付这种疾病。', 'Breaking Boundaries', 4, 0, 'senior', 'wordlist', 'elective2', 'U4', 'tackle a disease', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'vital', 'adj.', '/ˈvaɪtl/', '极其重要的,至关重要的', 'It is vital not to take any chances when fighting an outbreak.', '对抗疫情爆发时,绝不冒险是至关重要的。', 'Breaking Boundaries', 5, 0, 'senior', 'wordlist', 'elective2', 'U4', 'of vital importance', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'comrade', 'n.', '/ˈkɒmrɪd/', '同志;(共患难的)朋友,伙伴', 'The health workers raised their glasses to their comrades from many nations.', '卫生工作者们向来自许多国家的同志举杯致意。', 'Breaking Boundaries', 6, 0, 'senior', 'wordlist', 'elective2', 'U4', 'comrades in arms', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'tragic', 'adj.', '/ˈtrædʒɪk/', '悲惨的,不幸的', 'He saw tragic scenes on the news and decided to offer his help.', '他在新闻里看到悲惨的场面,决定去提供帮助。', 'Breaking Boundaries', 7, 0, 'senior', 'wordlist', 'elective2', 'U4', 'tragic scenes', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'combat', 'v.', '/ˈkɒmbæt/', '防止,抑制;与……斗争', 'There are no borders for those who combat this terrible disease.', '对于抗击这种可怕疾病的人来说,没有边界。', 'Breaking Boundaries', 8, 0, 'senior', 'wordlist', 'elective2', 'U4', 'combat a disease', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'relieve', 'v.', '/rɪˈliːv/', '接替,给(某人)换班;缓解,减轻', 'Her mission was to relieve a doctor at the end of her posting.', '她的任务是接替一位即将结束派驻的医生。', 'Breaking Boundaries', 9, 0, 'senior', 'wordlist', 'elective2', 'U4', 'relieve a colleague', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'specialist', 'n.', '/ˈspeʃ(ə)lɪst/', '专家', 'Emma is a Canadian specialist in infectious diseases.', '艾玛是一位加拿大的传染病专家。', 'Breaking Boundaries', 10, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a specialist in', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'infectious', 'adj.', '/ɪnˈfekʃəs/', '传染性的,有传染性的', 'The clinic mainly treats patients with infectious diseases.', '这家诊所主要治疗患有传染病的病人。', 'Breaking Boundaries', 11, 0, 'senior', 'wordlist', 'elective2', 'U4', 'an infectious disease', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'clinic', 'n.', '/ˈklɪnɪk/', '诊所;门诊部', 'Wilton helped carry the very sick into the treatment clinic.', '威尔顿帮忙把重病患者抬进治疗诊所。', 'Breaking Boundaries', 12, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a treatment clinic', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'disinfect', 'v.', '/ˌdɪsɪnˈfekt/', '为……消毒,给……杀菌', 'He worked hard to disinfect clothing and surfaces every day.', '他每天努力给衣物和各种表面消毒。', 'Breaking Boundaries', 13, 0, 'senior', 'wordlist', 'elective2', 'U4', 'disinfect surfaces', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'outbreak', 'n.', '/ˈaʊtbreɪk/', '(疾病等的)爆发,突然发生', 'Alfonso had worked on disease outbreaks in several countries.', '阿方索曾在好几个国家参与应对疾病爆发。', 'Breaking Boundaries', 14, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a disease outbreak', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'devotion', 'n.', '/dɪˈvəʊʃ(ə)n/', '奉献;忠诚,挚爱', 'Their devotion to the cause shone from their eyes.', '他们对这项事业的奉献从眼神中闪现出来。', 'Breaking Boundaries', 15, 0, 'senior', 'wordlist', 'elective2', 'U4', 'devotion to a cause', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'miracle', 'n.', '/ˈmɪrək(ə)l/', '奇迹;意外的幸运事', 'Our efforts do sometimes end in miracles, even against all odds.', '尽管困难重重,我们的努力有时确实会以奇迹收场。', 'Breaking Boundaries', 16, 0, 'senior', 'wordlist', 'elective2', 'U4', 'end in a miracle', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'twin', 'adj.', '/twɪn/', '双胞胎的;成对的', 'The twin girls and their parents were all infected.', '那对双胞胎女孩和她们的父母都感染了。', 'Breaking Boundaries', 17, 0, 'senior', 'wordlist', 'elective2', 'U4', 'twin girls', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'ward', 'n.', '/wɔːd/', '病房', 'When we visited the ward the next morning, both boys were still alive.', '第二天早上我们去病房时,两个男孩都还活着。', 'Breaking Boundaries', 18, 0, 'senior', 'wordlist', 'elective2', 'U4', 'visit the ward', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'compensate', 'v.', '/ˈkɒmpənseɪt/', '弥补,补偿', 'This small success compensated for many less fortunate cases.', '这一小小的成功弥补了许多不那么幸运的病例。', 'Breaking Boundaries', 19, 0, 'senior', 'wordlist', 'elective2', 'U4', 'compensate for', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'collaborate', 'v.', '/kəˈlæbəreɪt/', '合作,协作', 'It is essential for us all to collaborate to build a better world.', '我们所有人通力合作来建设一个更美好的世界,这是必不可少的。', 'Breaking Boundaries', 20, 0, 'senior', 'wordlist', 'elective2', 'U4', 'collaborate with', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'mankind', 'n.', '/ˌmænˈkaɪnd/', '人类', 'We work to build a community with a shared future for mankind.', '我们致力于构建人类命运共同体。', 'Breaking Boundaries', 21, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a shared future for mankind', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'realistic', 'adj.', '/ˌrɪəˈlɪstɪk/', '(目标、希望)能够实现的;现实的', 'For minority actors, leading roles are now a more realistic hope.', '对少数族裔演员来说,担任主角如今是更现实的希望了。', 'Breaking Boundaries', 22, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a realistic hope', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'minority', 'n.', '/maɪˈnɒrɪti/', '少数派;少数;少数族裔', 'The report studied the roles given to women and minority actors.', '这份报告研究了分配给女性和少数族裔演员的角色。', 'Breaking Boundaries', 23, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a minority group', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'cast', 'v.', '/kɑːst/', '选派(角色);投掷,抛', 'Some studios still cast white actors as Asian characters.', '一些制片公司仍让白人演员出演亚洲角色。', 'Breaking Boundaries', 24, 0, 'senior', 'wordlist', 'elective2', 'U4', 'cast an actor', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'inclusive', 'adj.', '/ɪnˈkluːsɪv/', '包容广阔的;包括在内的', 'Cultural exchange helps us become more inclusive.', '文化交流帮助我们变得更加包容。', 'Breaking Boundaries', 25, 0, 'senior', 'wordlist', 'elective2', 'U4', 'an inclusive society', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'joint', 'adj.', '/dʒɔɪnt/', '联合的,共同的', 'Different countries make a joint effort to create a better world.', '不同国家共同努力来创造一个更美好的世界。', 'Breaking Boundaries', 26, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a joint effort', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'harmonious', 'adj.', '/hɑːˈməʊniəs/', '和睦的,融洽的;协调的', 'Together we can build a more harmonious and understanding world.', '我们携手就能建设一个更和谐、更包容理解的世界。', 'Breaking Boundaries', 27, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a harmonious world', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'mutual', 'adj.', '/ˈmjuːtʃuəl/', '共有的,共同的;相互的', 'When cultures meet, both sides can enjoy the mutual benefits.', '当不同文化相遇时,双方都能享受共同的益处。', 'Breaking Boundaries', 28, 0, 'senior', 'wordlist', 'elective2', 'U4', 'mutual benefits', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'rewarding', 'adj.', '/rɪˈwɔːdɪŋ/', '值得做的,有意义的', 'It was rewarding to see how our work helped people from different cultures.', '看到我们的工作帮助了来自不同文化的人们,很有意义。', 'Breaking Boundaries', 29, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a rewarding experience', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'mount', 'v.', '/maʊnt/', '走上,登上;(逐渐)增加', 'A tall, thin man mounted the platform and began to speak.', '一位瘦高的男子走上讲台开始讲话。', 'Breaking Boundaries', 30, 0, 'senior', 'wordlist', 'elective2', 'U4', 'mount a platform', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'civil', 'adj.', '/ˈsɪv(ə)l/', '公民的,国民的;国内的', 'For two years, the country had been deep in a civil war.', '两年来,这个国家深陷一场内战之中。', 'Breaking Boundaries', 31, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a civil war', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'civilian', 'adj.', '/sɪˈvɪljən/', '平民的;百姓的', 'Lincoln understood the feelings of the civilian people.', '林肯理解平民百姓的感受。', 'Breaking Boundaries', 32, 0, 'senior', 'wordlist', 'elective2', 'U4', 'civilian people', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'division', 'n.', '/dɪˈvɪʒ(ə)n/', '分歧,分裂;分配;部门', 'It was time to remove the divisions between North and South.', '是时候消除南北之间的分裂了。', 'Breaking Boundaries', 33, 0, 'senior', 'wordlist', 'elective2', 'U4', 'remove divisions', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'conceive', 'v.', '/kənˈsiːv/', '构想,设想;想象', 'The new nation was conceived in liberty and dedicated to equality.', '这个新国家孕育于自由,致力于平等。', 'Breaking Boundaries', 34, 0, 'senior', 'wordlist', 'elective2', 'U4', 'be conceived in', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'liberty', 'n.', '/ˈlɪbəti/', '自由', 'The founders brought forth a nation dedicated to liberty.', '缔造者们创建了一个献身于自由的国家。', 'Breaking Boundaries', 35, 0, 'senior', 'wordlist', 'elective2', 'U4', 'fight for liberty', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'dedicate', 'v.', '/ˈdedɪkeɪt/', '致力于,献身于;把……奉献给', 'We come here to dedicate this ground to those who died for freedom.', '我们来到这里,把这片土地献给那些为自由而牺牲的人。', 'Breaking Boundaries', 36, 0, 'senior', 'wordlist', 'elective2', 'U4', 'dedicate oneself to', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'endure', 'v.', '/ɪnˈdjʊə/', '持续存在;忍受,忍耐', 'He asked whether such a nation could long endure.', '他发问:这样一个国家能否长久存续。', 'Breaking Boundaries', 37, 0, 'senior', 'wordlist', 'elective2', 'U4', 'long endure', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'battlefield', 'n.', '/ˈbætlfiːld/', '战场', 'They met on a great battlefield of that war.', '他们相聚在那场战争的一处大战场上。', 'Breaking Boundaries', 38, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a great battlefield', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'portion', 'n.', '/ˈpɔːʃ(ə)n/', '一部分;一份', 'They came to dedicate a portion of the field as a resting place.', '他们前来把这片土地的一部分辟为安息之所。', 'Breaking Boundaries', 39, 0, 'senior', 'wordlist', 'elective2', 'U4', 'a portion of', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'altogether', 'adv.', '/ˌɔːltəˈɡeðə/', '完全,全部;总共', 'It is altogether fitting that we should honour those who died here.', '我们缅怀在此牺牲的人,这是完全恰当的。', 'Breaking Boundaries', 40, 0, 'senior', 'wordlist', 'elective2', 'U4', 'altogether fitting', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'detract', 'v.', '/dɪˈtrækt/', '减低,贬损,损害', 'Our poor words can add little or detract from their brave deeds.', '我们苍白的言辞既无法增添、也无法贬损他们英勇的事迹。', 'Breaking Boundaries', 41, 0, 'senior', 'wordlist', 'elective2', 'U4', 'detract from', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'nobly', 'adv.', '/ˈnəʊbli/', '高尚地,崇高地', 'The living must finish the work they so nobly carried on.', '活着的人必须完成他们如此崇高地推进的事业。', 'Breaking Boundaries', 42, 0, 'senior', 'wordlist', 'elective2', 'U4', 'nobly carry on', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'perish', 'v.', '/ˈperɪʃ/', '死亡,消亡', 'He hoped this government of the people would never perish from the earth.', '他希望这个民有的政府永不会从地球上消亡。', 'Breaking Boundaries', 43, 0, 'senior', 'wordlist', 'elective2', 'U4', 'perish from the earth', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'influential', 'adj.', '/ˌɪnfluˈenʃ(ə)l/', '有影响力的', 'Edgar Snow wrote influential books about China in the 1930s.', '埃德加·斯诺在20世纪30年代写了一些有影响力的关于中国的书。', 'Breaking Boundaries', 44, 0, 'senior', 'wordlist', 'elective2', 'U4', 'an influential book', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'communist', 'adj.', '/ˈkɒmjʊnɪst/', '共产主义的', 'His book told the stories of the Chinese communist movement from the inside.', '他的书从内部讲述了中国共产主义运动的故事。', 'Breaking Boundaries', 45, 0, 'senior', 'wordlist', 'elective2', 'U4', 'the communist movement', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'slave', 'n.', '/sleɪv/', '奴隶', 'Lincoln helped break the boundaries that kept the slaves in chains.', '林肯帮助打破了把奴隶束缚在枷锁中的界限。', 'Breaking Boundaries', 46, 0, 'senior', 'wordlist', 'elective2', 'U4', 'free the slaves', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'culture shock', 'n.', '/ˈkʌltʃə ʃɒk/', '文化冲击,文化震撼', 'Cultural exchange helps newcomers overcome culture shock more quickly.', '文化交流帮助新来者更快地克服文化冲击。', 'Breaking Boundaries', 47, 0, 'senior', 'wordlist', 'elective2', 'U4', 'overcome culture shock', NULL, 'fltrp');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'in vain', 'phrase', '/ɪn ˈveɪn/', '白白地,徒劳地', 'He promised that the dead should not have died in vain.', '他承诺,逝者绝不会白白牺牲。', 'Breaking Boundaries', 48, 0, 'senior', 'wordlist', 'elective2', 'U4', 'not die in vain', NULL, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u4.01', '①It is + 形容词 + to do(形式主语指代不定式)', 'A2', 11, '外研社版选择性必修第二册 U4 — 真正主语是后面的不定式短语,前面用 it 作形式主语:It is important/necessary/vital/possible to do…。that/this/there 都不能这样统领不定式,故只能用 it。', 1, 'elective2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u4.02', '②It is + 形容词/名词 + that 从句(形式主语指代从句)', 'A2', 11, '外研社版选择性必修第二册 U4 — 真正主语是 that 从句,前面用 it 作形式主语:It is true/clear/a pity/no surprise that…。that/this/there 在此都不成立,只能用 it。', 2, 'elective2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('fe2u4.03', '③It takes/seems/happens…;It is no use/good doing', 'A2', 11, '外研社版选择性必修第二册 U4 — 固定句式:It takes + 时间/精力 + to do、It seems/happens that…、It is no use/good doing sth。主语位置只能用 it,that/this/there 都不行。', 3, 'elective2', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'fltrp');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is important to remember that diseases respect no borders."', 'It', 'That', 'This', 'There', 'A', '真正主语是后面的不定式 to remember…,主语位置用形式主语 it;that/this/there 都无法这样统领不定式。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is necessary to disinfect every surface in the ward."', 'That', 'It', 'This', 'There', 'B', '形式主语 it 指代后面的不定式 to disinfect…;其余三项不能引出不定式真正主语。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is vital not to take any chances during an outbreak."', 'That', 'This', 'It', 'There', 'C', 'it 作形式主语,真正主语是 not to take any chances;that/this/there 均不成立。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is possible for doctors from many countries to work as one team."', 'That', 'This', 'There', 'It', 'D', 'It is possible (for sb) to do 的形式主语结构,只能用 it。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is hard to imagine the courage these health workers show."', 'It', 'That', 'This', 'There', 'A', '真正主语是不定式 to imagine…,前面用形式主语 it。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is wonderful to see strangers join together in a common cause."', 'That', 'It', 'This', 'There', 'B', 'it 指代后面的不定式 to see…;that/this/there 不能引出不定式主语。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is dangerous to enter the clinic without proper protection."', 'That', 'This', 'It', 'There', 'C', '形式主语 it + 真正主语 to enter…,只能用 it。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is wise to listen carefully before you judge another culture."', 'That', 'This', 'There', 'It', 'D', 'It is wise to do 结构,it 作形式主语。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is essential for us all to collaborate to build a better world."', 'It', 'That', 'This', 'There', 'A', '真正主语是 to collaborate…,主语位置用形式主语 it。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is difficult to describe the bonds formed in such a crisis."', 'That', 'It', 'This', 'There', 'B', 'it 指代后面的不定式 to describe…;其余三项不成立。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is inspiring to have comrades from every continent on the team."', 'That', 'This', 'It', 'There', 'C', '形式主语 it + 真正主语 to have…,只能用 it。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is rewarding to help people who have lost everything."', 'That', 'This', 'There', 'It', 'D', 'It is rewarding to do,it 作形式主语指代不定式。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is not easy to relieve a doctor at the end of a long posting."', 'It', 'That', 'This', 'There', 'A', '真正主语是 to relieve…,前面用形式主语 it。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is useful to learn a few words of the local language first."', 'That', 'It', 'This', 'There', 'B', 'it 指代后面的不定式 to learn…;that/this/there 不能这样使用。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is common to hear several languages spoken in the same room."', 'That', 'This', 'It', 'There', 'C', 'It is common to do,it 作形式主语。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is brave of him to risk his life to combat the disease."', 'That', 'This', 'There', 'It', 'D', 'It is brave of sb to do 的形式主语结构,只能用 it。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is natural to feel nervous before your first day in the ward."', 'It', 'That', 'This', 'There', 'A', '真正主语是 to feel nervous…,前面用形式主语 it。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is safe to assume that teamwork saves more lives."', 'That', 'It', 'This', 'There', 'B', '形式主语 it 指代不定式 to assume…;其余三项不成立。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is impossible to win this fight without working together."', 'That', 'This', 'It', 'There', 'C', 'It is impossible to do,it 作形式主语。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.01'), '"____ is worthwhile to break down the boundaries between people."', 'That', 'This', 'There', 'It', 'D', 'It is worthwhile to do,真正主语是不定式,用形式主语 it。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is true that disease does not respect national boundaries."', 'It', 'That', 'This', 'There', 'A', '真正主语是 that 从句,主语位置用形式主语 it;that/this/there 都不能这样引出从句主语。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is clear that the whole team shares one common goal."', 'That', 'It', 'This', 'There', 'B', 'it 作形式主语指代后面的 that 从句,其余三项不成立。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is obvious that no single country can fight an outbreak alone."', 'That', 'This', 'It', 'There', 'C', 'It is obvious that… 的形式主语结构,只能用 it。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is certain that their devotion saved many lives."', 'That', 'This', 'There', 'It', 'D', '真正主语是 that 从句,前面用形式主语 it。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is a pity that some patients could not be saved."', 'It', 'That', 'This', 'There', 'A', 'It is a pity that…,名词后接从句,用形式主语 it。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is a fact that the death rate in the clinic was very high."', 'That', 'It', 'This', 'There', 'B', 'It is a fact that…,it 作形式主语指代从句。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is no surprise that the boys'' recovery amazed everyone."', 'That', 'This', 'It', 'There', 'C', 'It is no surprise that…,主语位置用形式主语 it。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is no wonder that such work creates powerful bonds between people."', 'That', 'This', 'There', 'It', 'D', '固定句式 It is no wonder that…,只能用 it。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is well known that Edgar Snow wrote influential books about China."', 'It', 'That', 'This', 'There', 'A', 'It is well known that…,it 作形式主语指代从句。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is likely that more volunteers will join the mission next year."', 'That', 'It', 'This', 'There', 'B', 'It is likely that…,真正主语是 that 从句,用形式主语 it。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is strange that we still build walls between different cultures."', 'That', 'This', 'It', 'There', 'C', 'It is strange that…,主语位置用形式主语 it。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is lucky that both brothers made a full recovery."', 'That', 'This', 'There', 'It', 'D', 'It is lucky that…,it 指代后面的从句。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is a shame that prejudice still keeps some people apart."', 'It', 'That', 'This', 'There', 'A', 'It is a shame that…,名词后接从句,用形式主语 it。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is natural that newcomers feel culture shock at first."', 'That', 'It', 'This', 'There', 'B', 'It is natural that…,真正主语是从句,用形式主语 it。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is amazing that people from so many nations work side by side."', 'That', 'This', 'It', 'There', 'C', 'It is amazing that…,只能用形式主语 it。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is important that we remember the soldiers who died here."', 'That', 'This', 'There', 'It', 'D', 'It is important that…,主语位置用形式主语 it。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is a good thing that cultures can learn from one another."', 'It', 'That', 'This', 'There', 'A', 'It is a good thing that…,it 作形式主语指代从句。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is sad that the civil war divided so many families."', 'That', 'It', 'This', 'There', 'B', 'It is sad that…,真正主语是从句,用形式主语 it。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is fortunate that technology now connects us across the world."', 'That', 'This', 'It', 'There', 'C', 'It is fortunate that…,主语位置用形式主语 it。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.02'), '"____ is encouraging that minority actors are getting more leading roles."', 'That', 'This', 'There', 'It', 'D', 'It is encouraging that…,it 指代后面的 that 从句。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ takes great courage to work in a disease clinic."', 'It', 'That', 'This', 'There', 'A', '固定句式 It takes + 精力 + to do,主语位置只能用 it;that/this/there 都不行。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ takes many hands to build a community with a shared future."', 'That', 'It', 'This', 'There', 'B', 'It takes … to do,只能用 it。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ took two years of civil war before the nation found peace."', 'That', 'This', 'It', 'There', 'C', 'It took + 时间 的句式,主语用 it。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ takes patience to overcome the culture shock of a new country."', 'That', 'This', 'There', 'It', 'D', 'It takes + 品质 + to do,只能用 it。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ seems that the world is getting smaller every year."', 'It', 'That', 'This', 'There', 'A', 'It seems that… 的固定句式,主语只能用 it;there seems 后只能接 to be。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ seems that no border can stop people from helping one another."', 'That', 'It', 'This', 'There', 'B', 'It seems that…,主语位置用 it。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ seemed that at least three languages were being spoken nearby."', 'That', 'This', 'It', 'There', 'C', 'It seemed that…,只能用 it。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ happens that he was the only Chinese doctor on the team."', 'That', 'This', 'There', 'It', 'D', 'It happens that… 的固定句式,主语用 it。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ happened that the two boys survived against all odds."', 'It', 'That', 'This', 'There', 'A', 'It happened that…,主语位置只能用 it。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ is no use worrying about mistakes when you learn a new culture."', 'That', 'It', 'This', 'There', 'B', 'It is no use doing sth 的固定句式,主语用 it。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ is no use pretending that prejudice has disappeared."', 'That', 'This', 'It', 'There', 'C', 'It is no use doing,只能用 it。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ is no good blaming others for the divisions in society."', 'That', 'This', 'There', 'It', 'D', 'It is no good doing sth,主语位置用 it。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ is no good waiting for someone else to break the boundary."', 'It', 'That', 'This', 'There', 'A', 'It is no good doing,只能用 it。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ takes time for two countries to build mutual trust."', 'That', 'It', 'This', 'There', 'B', 'It takes time (for sb) to do,主语用 it。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ seems that technology has brought distant cultures together."', 'That', 'This', 'It', 'There', 'C', 'It seems that…,主语位置只能用 it。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ takes real devotion to relieve a doctor in a war zone."', 'That', 'This', 'There', 'It', 'D', 'It takes + 品质 + to do,只能用 it。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ is no use complaining about a problem you will not tackle."', 'It', 'That', 'This', 'There', 'A', 'It is no use doing sth,主语用 it。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ happens that many great speeches have broken old boundaries."', 'That', 'It', 'This', 'There', 'B', 'It happens that…,主语位置只能用 it。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ takes courage to mount a platform and speak for equality."', 'That', 'This', 'It', 'There', 'C', 'It takes courage to do,主语用 it。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='fltrp' AND volume='elective2' AND unit='U4' AND code='fe2u4.03'), '"____ is no good keeping silent when people are treated unfairly."', 'That', 'This', 'There', 'It', 'D', 'It is no good doing sth,只能用 it。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Doctors Without Borders', 'Médecins Sans Frontières, known in English as Doctors Without Borders, was started in Paris in 1971 by a small group of doctors and journalists. From the very beginning, its idea was simple but powerful: medical help should cross every boundary. The organisation is independent and makes no profit. Its mission is to bring care to people who are affected by war, disease, natural disasters or a lack of basic health services. It helps people only according to their need, and it does not matter which country they come from. Those in the most serious and immediate danger are always treated first. Today the group has more than sixty thousand team members from over one hundred and fifty countries and regions. Doctors, nurses, drivers and local volunteers work side by side, often in places that other organisations have left. For them, a patient is never a foreigner. As one worker put it, there are no borders for doctors, for patients, or for anyone fighting a terrible disease.', '说明·无国界医生组织', 166, '[{"q":"What is the main idea of the passage?","answer":"A","options":["A group that brings medical care across all borders.","A travel company for tourists.","A school that trains journalists.","A factory that makes medicine for sale."],"explanation":"全文围绕''医疗援助跨越一切界限''的组织展开,是对其宗旨的概括。"},{"q":"Who receives treatment first, according to the text?","answer":"B","options":["The richest patients.","Those in the greatest and most urgent danger.","Only local citizens.","People from one chosen country."],"explanation":"原文说处于最严重、最紧迫危险中的人优先受治,为转述。"},{"q":"How does the worker describe the group''s view of patients?","answer":"A","options":["No patient is treated as a foreigner.","Patients are seen as customers.","Patients are judged by their wealth.","Only doctors matter, not patients."],"explanation":"末句''对他们而言病人从不是外国人''的转述。"}]'::jsonb, '[{"word":"boundary","cn":"界限,边界"},{"word":"mission","cn":"使命,任务"},{"word":"independent","cn":"独立的"}]'::jsonb, 2, 'elective2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A Doctor''s Journal', 'When I saw the tragic scenes on the news, I felt it was my duty as a doctor to go and offer help. I knew I was putting my life at risk, but I thought, if I don''t do it, who will? So I joined the team fighting the outbreak. On my first day, a colleague spent an hour talking me through the daily routine. As she spoke, I could hear at least three different languages around us. My new comrades came from every continent except one. There was a young local man who carried the very sick into the clinic and worked hard to disinfect everything. There was a retired official whose team taught families how to prevent infection. Although the death rate was very high, we never gave up on a patient. One morning, against all odds, two infected brothers were still alive, and they later made a full recovery. That small success made up for many sadder cases. To share such work creates a powerful bond between people who have come from very different places.', '记叙·一位医生的抗疫日记', 178, '[{"q":"Why did the writer decide to join the team?","answer":"B","options":["He felt it was his duty to help.","He wanted to become famous.","He was ordered to go by the army.","He was looking for a holiday."],"explanation":"干扰项;正确答案见下条逻辑。原文''我觉得作为医生这是我的责任''。"},{"q":"What happened to the two infected brothers?","answer":"C","options":["They both died the first night.","They were sent home untreated.","They survived and fully recovered.","They were never found."],"explanation":"原文说兄弟俩奇迹般存活并完全康复,为转述。"},{"q":"What does the writer say such shared work creates?","answer":"D","options":["More borders between nations.","A wish to give up the job.","Less respect among the team.","Strong bonds between very different people."],"explanation":"末句''共同工作在不同背景的人之间建立起牢固纽带''的转述。"}]'::jsonb, '[{"word":"tragic","cn":"悲惨的"},{"word":"comrade","cn":"同志,伙伴"},{"word":"disinfect","cn":"消毒"}]'::jsonb, 2, 'elective2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Global Village', 'These days, people all over the world are becoming more and more connected, as if the planet were getting smaller and we were all living in one global village. Technology is largely responsible for bringing us together. Channels such as the mobile phone and the Internet have made it possible to speak instantly with someone on the other side of the world. This lets us form close ties with people of completely different cultures. Television, too, is like a window on the world, giving us quick and easy access to other ways of life. Cultural exchange helps us become more inclusive and to overcome culture shock. But being inclusive does not mean that our cultures will simply melt into one. Instead, it is about countries and people making a joint effort to come together and create a more harmonious world. In this way, everyone can enjoy the mutual benefits. The boundaries between cultures do not disappear; they just become bridges that we can cross.', '说明·全球村与文化交流', 164, '[{"q":"What is mainly responsible for bringing people together?","answer":"A","options":["Modern technology.","Bad weather.","Long sea voyages.","Old paper maps."],"explanation":"原文''技术在很大程度上把人们联系到一起'',为转述。"},{"q":"What does being inclusive NOT mean, according to the text?","answer":"B","options":["Learning from other cultures.","All cultures melting into a single one.","Making a joint effort together.","Crossing cultural boundaries."],"explanation":"原文说包容不意味着文化融为一体,为转述。"},{"q":"How are cultural boundaries described at the end?","answer":"C","options":["As walls that must stay forever.","As reasons to stop talking.","As bridges that can be crossed.","As mistakes to be deleted."],"explanation":"末句把界限比作''可以跨越的桥'',为转述。"}]'::jsonb, '[{"word":"inclusive","cn":"包容的"},{"word":"harmonious","cn":"和谐的"},{"word":"mutual","cn":"共同的,相互的"}]'::jsonb, 2, 'elective2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'The Words That Changed a Nation', 'On a grey afternoon in November 1863, a tall, thin man mounted a platform in a field in Gettysburg and began to speak. The place was the site of a recent battle where thousands of soldiers had died. The man was Abraham Lincoln, and he had come to honour those who had given their lives. His speech was only about two hundred and seventy words long and lasted just two minutes, yet it changed the minds of his people and helped shape a nation. At that time the country was bitterly divided by a civil war between the slave-owning South and the free North. The cost had been terrible, and many people had lost hope. Lincoln understood the feelings of ordinary civilians. His words gave them belief and a reason to look to the future. He offered a new vision of what the nation should be, one built on equality. Now, he said, it was up to the living to remove not only the divisions between North and South, but the boundaries between black and white.', '记叙·林肯葛底斯堡演说', 176, '[{"q":"What was special about Lincoln''s speech?","answer":"D","options":["It lasted a whole day.","It was about ten thousand words.","It was never actually given.","It was short but changed the nation."],"explanation":"原文强调演说短小却改变了国家,为转述。"},{"q":"Why had many people lost hope at that time?","answer":"A","options":["Because of a costly civil war.","Because of a long drought.","Because of a lack of schools.","Because of a foreign invasion."],"explanation":"原文说内战使国家分裂、代价惨重、人们失去希望,为转述。"},{"q":"What did Lincoln say the living should now do?","answer":"B","options":["Forget the soldiers who died.","Remove the divisions and boundaries among people.","Build higher walls between regions.","Leave the country for good."],"explanation":"末句''消除南北分裂与黑白界限''的转述。"}]'::jsonb, '[{"word":"mount","cn":"登上"},{"word":"civil war","cn":"内战"},{"word":"division","cn":"分裂"}]'::jsonb, 2, 'elective2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'An American Friend', 'Edgar Snow was an American journalist who wrote influential books and articles about China in the 1930s. At a time when very little was known about the country in the Western world, his 1937 book Red Star Over China broke down the boundaries of misunderstanding. It told the stories of the Chinese communist movement from the inside, and it did so in a way few outsiders ever managed. Snow was not the only foreign reporter to visit China in those years, but what set him apart was that he actually spent time with the Chinese Red Army. He listened to ordinary soldiers, watched their daily lives and talked with their leaders. His honest accounts of events such as the Long March captured the spirit of the people living through them. Because of this, Snow has long been called "our American friend". He risked his own safety to reach the heart of the story and to correct prejudice, building a bridge of understanding between two very different worlds.', '说明·埃德加·斯诺打破隔阂', 167, '[{"q":"What did Snow''s 1937 book mainly do?","answer":"C","options":["It taught people how to farm.","It sold maps of Western cities.","It broke down boundaries of misunderstanding about China.","It hid the truth about China."],"explanation":"原文说该书打破了西方对中国的隔阂,为转述。"},{"q":"What set Snow apart from other foreign reporters?","answer":"D","options":["He never left his hotel.","He could not speak any English.","He wrote only about Europe.","He spent real time with the Red Army."],"explanation":"原文''让他与众不同的是他真正与红军相处'',为转述。"},{"q":"Why is Snow remembered as \"our American friend\"?","answer":"A","options":["Because he built understanding between two worlds.","Because he sold many newspapers.","Because he was born in China.","Because he never took any risks."],"explanation":"末段说他冒险纠正偏见、在两个世界间架起理解之桥,为转述。"}]'::jsonb, '[{"word":"influential","cn":"有影响力的"},{"word":"communist","cn":"共产主义的"},{"word":"prejudice","cn":"偏见"}]'::jsonb, 2, 'elective2', 'U4', 'fltrp');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Breaking Boundaries on Screen', 'A recent report on diversity in Hollywood studied two hundred films and more than one thousand television shows. It found some good news: getting roles in American film and television is no longer quite so difficult for women and minority actors. Becoming a leading actor is now a more realistic hope for performers from minority backgrounds, and women are writing and directing films more often than before. This is a small but important advance against unfair treatment based on gender or race. Yet the report also showed that there is still a long way to go. Leading roles are more likely to be given to white actors, and Asian American performers in particular still face many problems. Even now, some studios cast white actors as Asian characters, which many people find unacceptable. Still, the overall message is hopeful. Step by step, the screen is becoming a place where more kinds of people can see themselves, and where old boundaries are slowly being pushed back.', '说明·银幕上的多元进步', 164, '[{"q":"What good news did the report find?","answer":"B","options":["All cinemas have closed down.","Acting roles have become easier to get for many performers.","Films are no longer made in America.","Only men can direct now."],"explanation":"原文说女性和少数族裔获得角色不再那么难,为转述。"},{"q":"Which group still faces many problems, according to the text?","answer":"C","options":["White male directors.","Cinema owners.","Asian American performers.","Film critics."],"explanation":"原文特别提到亚裔美国演员仍面临许多问题,为转述。"},{"q":"What is the overall message of the report?","answer":"D","options":["Nothing has changed at all.","The situation is getting worse.","Films should no longer be made.","Progress is real though slow."],"explanation":"末段说尽管仍有差距,整体是充满希望、界限正被慢慢推开,为转述。"}]'::jsonb, '[{"word":"minority","cn":"少数族裔"},{"word":"realistic","cn":"能实现的"},{"word":"cast","cn":"选派(角色)"}]'::jsonb, 2, 'elective2', 'U4', 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'A Volunteer Teacher Abroad', 'Last summer I joined a teaching (1)____ in a small town far from home. Before I left, I was worried about culture (2)____, because everything would be so new. At first the food, the language and the daily habits all felt (3)____ to me. But the local teachers were warm and (4)____, and they helped me settle in. Little by little, I learned to (5)____ their way of life instead of judging it. We made a (6)____ effort to understand each other, and soon the classroom felt like one big family. By the end, my students and I could (7)____ across every difference. It was the most (8)____ experience of my life. I realised that the (9)____ between cultures are not walls but bridges. Now I cannot (10)____ to go back and do it all again.', 136, 2, '[{"q":"1","answer":"A","options":["project","price","noise","machine"],"explanation":"a teaching project 支教项目。"},{"q":"2","answer":"B","options":["price","shock","song","garden"],"explanation":"culture shock 文化冲击。"},{"q":"3","answer":"C","options":["cheap","loud","strange","heavy"],"explanation":"felt strange 感到陌生。"},{"q":"4","answer":"D","options":["angry","lazy","rude","welcoming"],"explanation":"warm and welcoming 热情友好。"},{"q":"5","answer":"A","options":["appreciate","forget","waste","sell"],"explanation":"appreciate their way of life 欣赏。"},{"q":"6","answer":"B","options":["empty","joint","single","false"],"explanation":"a joint effort 共同努力。"},{"q":"7","answer":"C","options":["fight","argue","connect","shout"],"explanation":"connect across differences 相互沟通。"},{"q":"8","answer":"D","options":["boring","useless","painful","rewarding"],"explanation":"the most rewarding experience 最有意义的经历。"},{"q":"9","answer":"A","options":["boundaries","prices","machines","noises"],"explanation":"boundaries between cultures 文化间的界限。"},{"q":"10","answer":"B","options":["sell","wait","lose","drop"],"explanation":"cannot wait to 迫不及待。"}]'::jsonb, 1, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'Joining the Relief Team', 'When Lina heard about the disease (1)____ in a distant country, she signed up to help. She was a young nurse, and she knew the work would put her life at (2)____. On her first day, an experienced colleague showed her the daily (3)____ in the clinic. Lina helped clean and (4)____ the rooms so that no infection could spread. The team came from many nations, yet they worked as one, sharing a deep (5)____ to their patients. Although the danger was real, they never (6)____ up on anyone. One night a whole family arrived, all of them (7)____. The team did everything they could, and against all (8)____ two of the children survived. That small (9)____ gave everyone fresh hope. Lina later wrote that helping others had taught her there are no (10)____ when people truly care.', 138, 2, '[{"q":"1","answer":"C","options":["garden","price","outbreak","song"],"explanation":"disease outbreak 疫情爆发。"},{"q":"2","answer":"D","options":["price","noise","shop","risk"],"explanation":"put one''s life at risk 冒生命危险。"},{"q":"3","answer":"A","options":["routine","weather","market","ticket"],"explanation":"the daily routine 日常工作流程。"},{"q":"4","answer":"B","options":["sell","disinfect","break","lose"],"explanation":"disinfect the rooms 给房间消毒。"},{"q":"5","answer":"C","options":["machine","price","devotion","noise"],"explanation":"devotion to patients 对病人的奉献。"},{"q":"6","answer":"D","options":["look","stand","got","gave"],"explanation":"never gave up 从不放弃(过去时)。"},{"q":"7","answer":"A","options":["infected","happy","rich","asleep"],"explanation":"all of them infected 全部被感染。"},{"q":"8","answer":"B","options":["prices","odds","songs","rooms"],"explanation":"against all odds 尽管困难重重。"},{"q":"9","answer":"C","options":["loss","noise","success","price"],"explanation":"that small success 那个小小的成功。"},{"q":"10","answer":"D","options":["prices","tickets","gardens","boundaries"],"explanation":"no boundaries 没有界限。"}]'::jsonb, 2, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'Our Shared Future Project', 'This term our class started a project about building a community with a (1)____ future. Each group chose a global problem and looked for ways that countries could (2)____ to solve it. My group studied how nations work together to (3)____ diseases that cross borders. We learned that no single country can win such a fight (4)____. Real progress depends on a (5)____ effort by many partners. We also read about people whose (6)____ to others changed the world. Their stories were truly (7)____, and they made us want to do more. At the end, each group gave a short talk to (8)____ what we had found. Our teacher said the most important lesson was simple: when we are (9)____ and open to one another, everyone enjoys the (10)____ benefits. I will never forget that idea.', 136, 2, '[{"q":"1","answer":"A","options":["shared","broken","lost","empty"],"explanation":"a shared future 共同的未来。"},{"q":"2","answer":"B","options":["argue","collaborate","compete","refuse"],"explanation":"collaborate to solve 合作解决。"},{"q":"3","answer":"C","options":["sell","enjoy","tackle","hide"],"explanation":"tackle diseases 应对疾病。"},{"q":"4","answer":"D","options":["together","loudly","early","alone"],"explanation":"win the fight alone 独自取胜。"},{"q":"5","answer":"A","options":["joint","single","false","empty"],"explanation":"a joint effort 共同努力。"},{"q":"6","answer":"B","options":["price","devotion","noise","weather"],"explanation":"devotion to others 对他人的奉献。"},{"q":"7","answer":"C","options":["boring","useless","inspiring","silent"],"explanation":"truly inspiring 真正鼓舞人心。"},{"q":"8","answer":"D","options":["hide","lose","forget","share"],"explanation":"share what we had found 分享发现。"},{"q":"9","answer":"A","options":["inclusive","selfish","lazy","afraid"],"explanation":"inclusive and open 包容开放。"},{"q":"10","answer":"B","options":["single","mutual","private","empty"],"explanation":"the mutual benefits 共同的益处。"}]'::jsonb, 3, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'A Festival from Far Away', 'My pen friend Sara invited me to join an online (1)____ of a festival from her country. I knew almost nothing about it, so at first I felt a little (2)____. Sara patiently explained the meaning behind each song and dance, and slowly the festival started to make (3)____ to me. I was amazed by how (4)____ her culture was, full of colour and history. We talked for hours, and it was (5)____ to learn so much from a friend on the other side of the world. Through the screen, the (6)____ between our two countries seemed to disappear. Sara said that sharing festivals is a (7)____ way to build understanding. I agreed, and I promised to (8)____ her about my own country''s holidays next time. Now we (9)____ to teach each other something new every month. Little by little, two strangers have become (10)____ friends.', 146, 2, '[{"q":"1","answer":"C","options":["price","machine","celebration","noise"],"explanation":"an online celebration 线上庆祝。"},{"q":"2","answer":"D","options":["rich","tall","loud","lost"],"explanation":"felt a little lost 有点不知所措。"},{"q":"3","answer":"A","options":["sense","money","noise","trouble"],"explanation":"make sense 变得明白。"},{"q":"4","answer":"B","options":["empty","rich","boring","silent"],"explanation":"how rich her culture was 文化多么丰富。"},{"q":"5","answer":"C","options":["useless","painful","rewarding","boring"],"explanation":"it was rewarding to learn 学到很多很有意义。"},{"q":"6","answer":"D","options":["price","noise","garden","boundary"],"explanation":"the boundary between countries 国家间的界限。"},{"q":"7","answer":"A","options":["great","bad","false","small"],"explanation":"a great way 一个好办法。"},{"q":"8","answer":"B","options":["hide","tell","lose","sell"],"explanation":"tell her about 告诉她。"},{"q":"9","answer":"C","options":["refuse","fail","plan","forget"],"explanation":"we plan to teach 我们打算。"},{"q":"10","answer":"D","options":["angry","distant","strange","close"],"explanation":"close friends 亲密的朋友。"}]'::jsonb, 4, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'A Speech About Heroes', 'For the school speech contest, I chose to talk about people who had (1)____ great boundaries. I began with a famous leader who, during a bitter (2)____ war, gave a short speech that gave his people hope. His words helped (3)____ the divisions between two sides. Then I spoke about a brave (4)____ who travelled far to report the truth and to correct (5)____ between nations. As I practised, I learned that it (6)____ courage to stand up and speak for what is right. On the day of the contest, I was nervous, but I reminded myself that it is no (7)____ keeping silent when something matters. My voice shook at first, yet the audience listened (8)____. When I finished, my teacher said my talk had truly been (9)____. I felt proud, because I had helped my classmates see how a few brave words can push back old (10)____.', 149, 2, '[{"q":"1","answer":"A","options":["broken","sold","lost","bought"],"explanation":"broken great boundaries 打破巨大界限。"},{"q":"2","answer":"B","options":["happy","civil","quiet","short"],"explanation":"a civil war 内战。"},{"q":"3","answer":"C","options":["build","raise","remove","sell"],"explanation":"remove the divisions 消除分裂。"},{"q":"4","answer":"D","options":["singer","farmer","driver","journalist"],"explanation":"a brave journalist 勇敢的记者。"},{"q":"5","answer":"A","options":["prejudice","machines","prices","gardens"],"explanation":"correct prejudice 纠正偏见。"},{"q":"6","answer":"B","options":["sells","takes","loses","hides"],"explanation":"it takes courage 需要勇气。"},{"q":"7","answer":"C","options":["price","song","use","noise"],"explanation":"it is no use keeping silent 保持沉默没有用。"},{"q":"8","answer":"D","options":["angrily","rudely","sadly","closely"],"explanation":"listened closely 认真聆听。"},{"q":"9","answer":"A","options":["inspiring","boring","useless","silent"],"explanation":"truly inspiring 真正鼓舞人心。"},{"q":"10","answer":"B","options":["prices","boundaries","tickets","machines"],"explanation":"old boundaries 旧的界限。"}]'::jsonb, 5, 'fltrp');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective2', 'U4', 'Sport Without Borders', 'Few things bring the world together like (1)____ does. When a big match is played, people from every country watch the same game at the same (2)____. On the field, players from different nations shake hands and show (3)____ respect, no matter who wins. Fans who do not even share a language can still (4)____ the same goal and cheer as one. In this way, sport helps to break down the (5)____ between strangers. I once watched an international final with visitors from three countries, and it was (6)____ to feel like one happy crowd. We could not all talk easily, but our smiles were (7)____ enough. Many people believe that sport is a (8)____ way to build friendship between nations. It teaches us to play fair, to (9)____ with one another, and to enjoy our differences. After that night, I truly understood that the love of a game knows no (10)____.', 152, 2, '[{"q":"1","answer":"C","options":["price","noise","sport","machine"],"explanation":"like sport does 像体育那样。"},{"q":"2","answer":"D","options":["price","garden","shop","time"],"explanation":"at the same time 同一时间。"},{"q":"3","answer":"A","options":["mutual","empty","false","single"],"explanation":"mutual respect 相互尊重。"},{"q":"4","answer":"B","options":["sell","share","hide","lose"],"explanation":"share the same goal 共享同一目标。"},{"q":"5","answer":"C","options":["prices","songs","boundaries","tickets"],"explanation":"break down the boundaries 打破界限。"},{"q":"6","answer":"D","options":["boring","painful","useless","rewarding"],"explanation":"it was rewarding to feel 感觉很有意义。"},{"q":"7","answer":"A","options":["clear","empty","wrong","loud"],"explanation":"our smiles were clear enough 笑容已足够清楚。"},{"q":"8","answer":"B","options":["bad","great","false","small"],"explanation":"a great way 一个好办法。"},{"q":"9","answer":"C","options":["argue","fight","collaborate","refuse"],"explanation":"collaborate with one another 相互协作。"},{"q":"10","answer":"D","options":["prices","machines","noises","boundaries"],"explanation":"knows no boundaries 没有界限。"}]'::jsonb, 6, 'fltrp');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Volunteering Abroad', '外研社版选择性必修第二册 U4 · dialogue', 3, 'Mia: I''ve signed up to volunteer at a children''s clinic in another country this summer.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 Help Across Borders', '外研社版选择性必修第二册 U4 · passage', 2, 'An organisation called Doctors Without Borders was founded in Paris many years ago.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Feeling at Home Abroad', '外研社版选择性必修第二册 U4 · dialogue', 3, 'Ken: How was your first week living in London, Yuki?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 A Speech That Mattered', '外研社版选择性必修第二册 U4 · passage', 2, 'In 1863, a leader stood up in a field where many soldiers had died.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Planning a Culture Day', '外研社版选择性必修第二册 U4 · dialogue', 3, 'Anna: Let''s plan our school''s International Culture Day together.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 The Power of Sport', '外研社版选择性必修第二册 U4 · passage', 2, 'Sport has a special power to bring people together.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Write a Speech about Someone Who Broke Boundaries(写一篇介绍打破界限者的演讲稿)', 'A Person Who Broke Boundaries', '假设你要在学校''打破界限''主题班会上做一个约100词的英语演讲,介绍一位帮助打破界限、增进不同人群或国家之间理解的人(如埃德加·斯诺、无国界医生中的某位志愿者,或你敬佩的人)。内容包括:① 这个人是谁;② 他/她打破了什么界限、怎么做到的;③ 你的评价与感受。注意恰当使用形式主语 it(It is … to do / It is … that …)。', 'Suppose you will give a short speech (about 100 words) at a class meeting on the theme "Breaking Boundaries". Introduce a person who has helped to break boundaries and increase understanding between different peoples or countries (e.g. Edgar Snow, an MSF volunteer, or someone you admire). Include: 1) who the person is; 2) what boundary he or she broke and how; 3) your comment and feelings. Try to use formal-subject "it" (It is … to do / It is … that …).', '["介绍人物身份(Today I''d like to talk about … / The person I admire is …)","说明打破的界限与做法(He/She broke … by …)","用形式主语 it 评价(It is clear that … / It is hard to … without …)","结尾表达感受与号召(It is up to us to …)"]'::jsonb, 70, 100, 'Hello, everyone. Today I''d like to talk about Edgar Snow, an American journalist who broke down boundaries of misunderstanding. In the 1930s, very little was known about China in the West. It was hard to learn the truth from far away, so Snow actually spent time with the people and told their stories from the inside. It is clear that his honest writing built a bridge between two very different worlds. For this, he is still remembered as "our American friend". It is inspiring to see how one brave person can change how nations see each other. It is up to us to keep breaking boundaries too. Thank you.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Edgar Snow was an American journalist who broke down boundaries of misunderstanding.","It is clear that his honest writing built a bridge between two very different worlds.","It is inspiring to see how one brave person can change how nations see each other.","It is up to us to keep breaking boundaries too."]'::jsonb, '[{"wrong":"Is important to break down boundaries.","correct":"It is important to break down boundaries.","note":"形式主语不能省,主语位置必须有 it。"},{"wrong":"It is clear that his writing built bridge.","correct":"It is clear that his writing built a bridge.","note":"单数可数名词 bridge 前要加冠词 a。"},{"wrong":"That is hard to learn the truth from far away.","correct":"It is hard to learn the truth from far away.","note":"统领后面的不定式真正主语,只能用形式主语 it,不用 that。"}]'::jsonb, '【打破界限演讲稿结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective2', 'U4', '{"title":"形式主语 it 速查(It is + adj./n. + to do / that 从句)","intro":"当真正的主语是不定式、that 从句或 -ing 时,英语习惯把它放到句末,主语位置用 it 占位,这个 it 就叫''形式主语''。判断口诀:句首主语位置是空的、后面跟着 to do 或 that 从句,就填 it。","table":{"headers":["句式","例句 / 说明"],"rows":[["It is + adj. + to do","It is vital not to take any chances.(真正主语 = 不定式)"],["It is + adj. + that 从句","It is true that disease respects no borders.(真正主语 = that 从句)"],["It is + n. + that 从句","It is a pity that some patients could not be saved."],["It takes + 时间/精力 + to do","It takes courage to break boundaries."],["It seems/happens that …","It seems that the world is getting smaller."],["It is no use/good doing","It is no use worrying about culture shock."]]},"specialRules":[{"rule":"主语位置只能用 it,不能用 that/this/there","mark":"It is important to … √ / That is important to … ×"},{"rule":"that 从句、不定式都可后置;-ing 多用于 It is no use/good doing","mark":"It is no use crying. √"},{"rule":"It is + adj. + of sb to do(评价人) vs for sb to do(说明难易)","mark":"It is kind of you to help / It is hard for me to decide"},{"rule":"there seems/happens 后只能接 to be,不接 that 从句","mark":"It seems that… √ / There seems that… ×"}],"why":["英语句子''头轻脚重'',不喜欢主语太长。把长长的不定式或从句放到句末,用 it 占住主语位置,句子更顺、重点更清楚。"],"gaokaoPoints":["语法填空/改错高频:主语位置空着、后接 to do 或 that 从句 → 填 it。","区分形式主语 it 与形式宾语 it(find/think/make it + adj. + to do);区分 it 与 there be。"],"examVsReal":[{"exam":"It is important to remember this.(考试规范)","real":"Remember this — it''s important.","note":"考试爱用完整形式主语句;口语常把重点前移、再补一句评价。"},{"exam":"It is no use worrying.(考试)","real":"No point worrying about it.","note":"口语常用 No point / There''s no point doing 表达同样意思。"}]}'::jsonb, 'fltrp');
